import { createServer } from "node:http";
import { randomUUID } from "node:crypto";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = path.join(ROOT, "data", "books.json");
const PORT = process.env.PORT || 3000;

async function loadBooks() {
  try {
    return JSON.parse(await readFile(DATA_FILE, "utf8"));
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

async function saveBooks(books) {
  await mkdir(path.dirname(DATA_FILE), { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2));
}

function esc(s) {
  return String(s ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk) => {
      body += chunk;
      if (body.length > 1e6) {
        reject(new Error("body too large"));
        req.destroy();
      }
    });
    req.on("end", () => resolve(new URLSearchParams(body)));
    req.on("error", reject);
  });
}

function layout(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 640px; margin: 2rem auto; padding: 0 1rem; color: #222; }
  h1 { font-size: 1.5rem; } h2 { font-size: 1.1rem; margin-top: 2rem; color: #555; }
  form { margin: 0; }
  .inline-form { display: inline; }
  input[type=text], textarea { width: 100%; padding: .5rem; box-sizing: border-box; border: 1px solid #ccc; border-radius: 6px; font: inherit; }
  button { padding: .4rem .8rem; border: 1px solid #ccc; border-radius: 6px; background: #f7f7f7; cursor: pointer; font: inherit; }
  button:hover { background: #eee; }
  ul { list-style: none; padding: 0; }
  li { padding: .6rem 0; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; align-items: center; gap: .5rem; }
  li a { color: #1a56b0; text-decoration: none; } li a:hover { text-decoration: underline; }
  .meta { color: #777; font-size: .9rem; }
  .add-form { display: flex; gap: .5rem; flex-wrap: wrap; margin-bottom: 1rem; }
  .add-form input { flex: 1; min-width: 10rem; }
  .error { background: #fdecea; color: #b02a1a; padding: .6rem; border-radius: 6px; }
  .share { display: flex; gap: .5rem; margin: 1rem 0; }
  .share input { flex: 1; }
  .empty { color: #999; font-style: italic; }
  .top { margin-top: 1rem; }
</style>
</head>
<body>
${content}
</body>
</html>`;
}

function bookItem(book, base) {
  const finishBtn =
    book.status === "reading"
      ? `<form class="inline-form" method="post" action="/books/${book.id}/finish">
           <button>Finish</button>
         </form>`
      : `<form class="inline-form" method="post" action="/books/${book.id}/reading">
           <button>Reopen</button>
         </form>`;
  return `<li>
    <span><a href="/books/${book.id}">${esc(book.title)}</a>
    <span class="meta"> — ${esc(book.author)}</span></span>
    ${finishBtn}
  </li>`;
}

function homePage(books, error) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");
  const list = (items) =>
    items.length
      ? `<ul>${items.map((b) => bookItem(b)).join("")}</ul>`
      : `<p class="empty">Nothing here yet.</p>`;
  return layout(
    "My books",
    `<h1>My books</h1>
     ${error ? `<p class="error">${esc(error)}</p>` : ""}
     <form class="add-form" method="post" action="/books">
       <input type="text" name="title" placeholder="Title" required>
       <input type="text" name="author" placeholder="Author">
       <button>Add book</button>
     </form>
     <h2>Currently reading</h2>
     ${list(reading)}
     <h2>Finished</h2>
     ${list(finished)}`
  );
}

function bookPage(book, base) {
  const shareUrl = `${base}/books/${book.id}`;
  const statusLabel = book.status === "finished" ? `Finished ${esc(book.finishedAt ?? "")}` : "Currently reading";
  const toggleForm =
    book.status === "reading"
      ? `<form method="post" action="/books/${book.id}/finish" class="top"><button>Mark as finished</button></form>`
      : `<form method="post" action="/books/${book.id}/reading" class="top"><button>Move back to reading</button></form>`;
  return layout(
    book.title,
    `<p><a href="/">← All books</a></p>
     <h1>${esc(book.title)}</h1>
     <p class="meta">by ${esc(book.author) || "unknown author"} · ${statusLabel}</p>
     <h2>Share this book</h2>
     <div class="share">
       <input type="text" readonly value="${esc(shareUrl)}" onclick="this.select()">
       <button type="button" onclick="navigator.clipboard.writeText(this.previousElementSibling.value).then(()=>{this.textContent='Copied';})">Copy</button>
     </div>
     <h2>Notes</h2>
     <form method="post" action="/books/${book.id}/notes">
       <textarea name="notes" rows="8" placeholder="Your notes...">${esc(book.notes)}</textarea>
       <p><button>Save notes</button></p>
     </form>
     ${toggleForm}`
  );
}

function notFound() {
  return { status: 404, body: layout("Not found", "<h1>Book not found</h1><p><a href='/'>← All books</a></p>") };
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

async function route(req, res) {
  const base = `http://${req.headers.host || `localhost:${PORT}`}`;
  const url = new URL(req.url, base);
  const books = await loadBooks();
  const findBook = () => books.find((b) => b.id === url.pathname.split("/")[2]);

  if (req.method === "GET" && url.pathname === "/") {
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
    res.end(homePage(books, url.searchParams.get("error")));
    return;
  }

  if (req.method === "POST" && url.pathname === "/books") {
    const form = await readForm(req);
    const title = (form.get("title") || "").trim();
    const author = (form.get("author") || "").trim();
    if (!title) {
      redirect(res, "/?error=Title+is+required");
      return;
    }
    const book = {
      id: randomUUID().slice(0, 8),
      title,
      author,
      status: "reading",
      notes: "",
      addedAt: new Date().toISOString().slice(0, 10),
    };
    books.push(book);
    await saveBooks(books);
    redirect(res, `/books/${book.id}`);
    return;
  }

  const bookMatch = /^\/books\/([\w-]+)(\/finish|\/reading|\/notes)?$/.exec(url.pathname);
  if (bookMatch) {
    const book = findBook();
    if (!book) {
      const page = notFound();
      res.writeHead(page.status, { "Content-Type": "text/html; charset=utf-8" });
      res.end(page.body);
      return;
    }
    const action = bookMatch[2];

    if (req.method === "GET" && !action) {
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      res.end(bookPage(book, base));
      return;
    }
    if (req.method === "POST" && action === "/finish") {
      book.status = "finished";
      book.finishedAt = new Date().toISOString().slice(0, 10);
      await saveBooks(books);
      redirect(res, `/books/${book.id}`);
      return;
    }
    if (req.method === "POST" && action === "/reading") {
      book.status = "reading";
      delete book.finishedAt;
      await saveBooks(books);
      redirect(res, `/books/${book.id}`);
      return;
    }
    if (req.method === "POST" && action === "/notes") {
      const form = await readForm(req);
      book.notes = form.get("notes") || "";
      await saveBooks(books);
      redirect(res, `/books/${book.id}`);
      return;
    }
  }

  res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
  res.end(notFound().body);
}

createServer(async (req, res) => {
  try {
    await route(req, res);
  } catch (err) {
    console.error(err);
    res.writeHead(500, { "Content-Type": "text/plain" });
    res.end("Server error");
  }
}).listen(PORT, () => console.log(`Books app running at http://localhost:${PORT}`));
